package com.forloops.programs;

public class ForStringArray {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		String[] names=
			{
					"java",
					"python",
					"sql",
					"azure",
					"claude"
			};
		
			for(String nm:names)
				System.out.println(nm);
	}

}
